<template><div class="office-page settings-page" v-loading="loading"><div class="office-toolbar"><h2>个人设置</h2><el-button type="primary" :loading="saving" @click="save">保存偏好</el-button></div>
<div class="office-two"><section class="office-section"><h3>外观与工作习惯</h3><div class="office-form">
<label>主题<select v-model="preferences.theme" @change="applyPreferences"><option value="system">跟随系统</option><option value="light">亮色</option><option value="dark">暗色</option></select></label>
<label>界面语言<select v-model="accountSettings.language"><option value="zh-CN">简体中文</option><option value="en-US">English（控件）</option></select></label>
<label>时区<el-input v-model="accountSettings.timezone" /></label>
<label>默认视图<select v-model="preferences.defaultView"><option value="/dashboard">工作台</option><option value="/documents">云文档</option><option value="/tasks">任务</option><option value="/im">消息</option></select></label>
<label>命令面板快捷键<select v-model="preferences.searchShortcut"><option v-for="key in ['k','j','p']" :key="key" :value="key">Ctrl / Cmd + {{ key.toUpperCase() }}</option></select></label>
</div></section><section class="office-section"><h3>编辑器偏好</h3><div class="office-form"><label>字体<select v-model="preferences.editorFont"><option v-for="font in ['Arial','Microsoft YaHei','SimSun','monospace']" :key="font">{{ font }}</option></select></label><label>默认字号<el-input-number v-model="preferences.editorSize" :min="12" :max="24" /></label><label>行距<el-input-number v-model="preferences.editorLineHeight" :min="1.2" :max="2.5" :step="0.1" /></label><label>正文宽度<select v-model="preferences.editorWidth"><option value="comfortable">标准</option><option value="wide">宽版</option></select></label></div></section></div>
<section class="office-section"><h3>通知偏好</h3><div class="preference-toggles"><el-checkbox v-model="accountSettings.emailNotify">邮件通知</el-checkbox><el-checkbox v-model="accountSettings.pushNotify">即时推送</el-checkbox><el-checkbox v-for="item in categories" :key="item.key" v-model="preferences.notifications[item.key]">{{ item.label }}</el-checkbox></div><router-link to="/settings/notifications">打开通知中心</router-link></section>
<section class="office-section"><h3>动态订阅</h3><form class="subscription-form" @submit.prevent="subscribe"><label>类型<select v-model="subscription.kind" @change="subscription.resourceId='' ; loadResources()"><option value="document">文档</option><option value="project">项目</option><option value="task">任务</option></select></label><label>内容<select v-model="subscription.resourceId" required><option value="" disabled>请选择</option><option v-for="r in resources" :key="r.id" :value="r.id">{{ r.title }}</option></select></label><label>频率<select v-model="subscription.frequency"><option value="realtime">实时</option><option value="daily">每日汇总</option></select></label><el-button native-type="submit">订阅</el-button></form><ul class="subscription-list"><li v-for="s in subscriptions" :key="s.id"><span>{{ s.title }} · {{ s.frequency==='daily'?'每日汇总':'实时' }}</span><el-button circle title="取消订阅" @click="unsubscribe(s.id)"><span class="material-symbols-outlined">close</span></el-button></li></ul><el-empty v-if="!subscriptions.length" description="暂无订阅" :image-size="50" /></section>
<div class="office-two"><section class="office-section"><h3>个人资料</h3><form class="office-form" @submit.prevent="saveProfile"><label>账号<el-input :model-value="account" readonly /></label><label>姓名<el-input v-model="nickname" maxlength="50" /></label><el-button native-type="submit" :loading="saving">保存资料</el-button></form></section><section class="office-section"><h3>修改密码</h3><form class="office-form" @submit.prevent="changePassword"><label>当前密码<el-input v-model="oldPassword" type="password" show-password autocomplete="current-password" /></label><label>新密码<el-input v-model="newPassword" type="password" show-password autocomplete="new-password" maxlength="20" /></label><label>确认新密码<el-input v-model="confirm" type="password" show-password autocomplete="new-password" /></label><el-button native-type="submit" :loading="saving">修改密码</el-button></form></section></div></div></template>
<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import request from '@/utils/request'
import {removeToken} from '@/utils/token'
import {wsClient} from '@/utils/wsClient'
import {preferences,accountSettings,loadPreferences,savePreferences,applyPreferences} from '@/utils/preferences'
const router=useRouter(),account=ref(''),nickname=ref(''),oldPassword=ref(''),newPassword=ref(''),confirm=ref(''),loading=ref(false),saving=ref(false)
const categories:{key:keyof typeof preferences.notifications;label:string}[]=[{key:'system',label:'系统'},{key:'collab',label:'协作'},{key:'task',label:'任务'},{key:'meeting',label:'会议'}]
const subscriptions=ref<any[]>([]),resources=ref<{id:string;title:string}[]>([]),subscription=ref({kind:'document',resourceId:'',frequency:'realtime'})
async function loadSubscriptions(){const r:any=await request.get('/notification/subscriptions');subscriptions.value=r.data}
async function loadResources(){const kind=subscription.value.kind;const r:any=await request.get(kind==='document'?'/document/list':kind==='project'?'/task/project/list':'/task/list',{params:{pageSize:100,spaceId:localStorage.getItem('active_space_id')}});resources.value=(r.data.records||r.data||[]).map((x:any)=>({id:String(x.docId||x.projectId||x.taskId),title:x.title||x.name}))}
async function subscribe(){if(!subscription.value.resourceId)return;try{await request.post('/notification/subscriptions',subscription.value);await loadSubscriptions();ElMessage.success('订阅已保存')}catch{}}
async function unsubscribe(id:string){try{await request.delete('/notification/subscriptions/'+id);await loadSubscriptions()}catch{}}
onMounted(async()=>{loading.value=true;try{const r:any=await request.get('/user/info');account.value=r.data.username;nickname.value=r.data.realName||'';await Promise.all([loadPreferences(),loadSubscriptions(),loadResources()])}catch{}finally{loading.value=false}})
async function save(){saving.value=true;try{await savePreferences();ElMessage.success('偏好已保存')}catch{}finally{saving.value=false}}
async function saveProfile(){if(!nickname.value.trim()){ElMessage.warning('请填写姓名');return}saving.value=true;try{await request.put('/user/profile',{nickname:nickname.value.trim()});ElMessage.success('资料已保存')}catch{}finally{saving.value=false}}
async function changePassword(){if(!oldPassword.value||newPassword.value.length<8||newPassword.value.length>20||newPassword.value!==confirm.value){ElMessage.warning('请检查旧密码、新密码长度及两次输入是否一致');return}saving.value=true;try{await request.put('/user/password',{oldPassword:oldPassword.value,newPassword:newPassword.value});await request.post('/auth/logout');removeToken();wsClient.disconnect();ElMessage.success('密码已修改，请重新登录');router.replace('/login')}catch{}finally{saving.value=false}}
</script>
<style scoped>.settings-page{display:grid;gap:var(--space-6)}select{padding:8px;border:1px solid var(--c-border);border-radius:var(--radius-sm);background:var(--c-surface);color:var(--c-text);min-width:0;max-width:100%}.preference-toggles{display:flex;flex-wrap:wrap;gap:12px}.subscription-form{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.subscription-form label{display:grid;gap:6px;min-width:140px;max-width:100%}.subscription-form select{max-width:400px}.subscription-list{list-style:none}.subscription-list li{display:flex;align-items:center;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--c-border-light)}@media(max-width:520px){.subscription-form label{width:100%}.subscription-form select{width:100%}}</style>
